package android.app;
public class PendingIntent implements android.os.Parcelable { public static final int FLAG_IMMUTABLE=0x04000000, FLAG_MUTABLE=0x02000000, FLAG_UPDATE_CURRENT=0x08000000, FLAG_CANCEL_CURRENT=0x10000000, FLAG_NO_CREATE=0x20000000, FLAG_ONE_SHOT=0x40000000; private android.content.Intent intent; private PendingIntent(android.content.Intent i) { intent=i; } public static PendingIntent getActivity(android.content.Context c,int request,android.content.Intent i,int flags) { return new PendingIntent(i); } public static PendingIntent getBroadcast(android.content.Context c,int request,android.content.Intent i,int flags) { return new PendingIntent(i); } public static PendingIntent getService(android.content.Context c,int request,android.content.Intent i,int flags) { return new PendingIntent(i); } public void cancel() {} public void send() throws CanceledException {} public int describeContents() { return 0; } public void writeToParcel(android.os.Parcel p,int flags) { p.writeParcelable(intent,flags); } public static final android.os.Parcelable.Creator<PendingIntent> CREATOR=new android.os.Parcelable.Creator<PendingIntent>() { public PendingIntent createFromParcel(android.os.Parcel p) { return new PendingIntent((android.content.Intent)p.readParcelable(null)); } public PendingIntent[] newArray(int n) { return new PendingIntent[n]; } }; public static class CanceledException extends Exception { public CanceledException() {} public CanceledException(String s) { super(s); } } }
